def eval_rpn(tokens: list[str]) -> int:
    """Evaluate an arithmetic expression given in Reverse Polish Notation.

    Supported operators: +, -, *, /. Division truncates toward zero.
    Operands are integers and may be negative (e.g. "-3").
    """
    stack: list[int] = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            else:  # '/': truncate toward zero (Python's // floors instead)
                result = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    result = -result
            stack.append(result)
        else:
            stack.append(int(token))

    return stack[-1]
