        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': div_trunc,
    }

    for token in tokens:
        if token in operators:
            right = stack.pop()
            left = stack.pop()
            stack.append(operators[token](left, right))
        else:
            stack.append(int(token))

    return stack.pop()
