def trap_rain_water(heights: list[int]) -> int:
    """Return the total units of rain water trapped between bars.

    Two-pointer technique: O(n) time, O(1) extra space.
    """
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = heights[left], heights[right]
    water = 0

    while left < right:
        if left_max <= right_max:
            left += 1
            h = heights[left]
            if h > left_max:
                left_max = h
            else:
                water += left_max - h
        else:
            right -= 1
            h = heights[right]
            if h > right_max:
                right_max = h
            else:
                water += right_max - h

    return water
