import re

_SEMVER_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)"
    r"(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?"
    r"(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$"
)


def _cmp(x, y) -> int:
    return (x > y) - (x < y)


def _parse(version: str):
    match = _SEMVER_RE.match(version.strip())
    if match is None:
        raise ValueError(f"invalid semantic version: {version!r}")
    major, minor, patch, prerelease, _build = match.groups()
    core = (int(major), int(minor), int(patch))
    identifiers = prerelease.split(".") if prerelease is not None else None
    return core, identifiers


def _compare_identifier(a: str, b: str) -> int:
    a_numeric = a.isascii() and a.isdigit()
    b_numeric = b.isascii() and b.isdigit()
    if a_numeric and b_numeric:
        return _cmp(int(a), int(b))
    if a_numeric != b_numeric:
        # Numeric identifiers always have lower precedence than alphanumeric ones.
        return -1 if a_numeric else 1
    # Alphanumeric identifiers are compared in ASCII sort order.
    return _cmp(a, b)


def _compare_prerelease(a, b) -> int:
    if a is None or b is None:
        # A version without a pre-release has higher precedence than one with.
        return _cmp(a is None, b is None)
    for ident_a, ident_b in zip(a, b):
        result = _compare_identifier(ident_a, ident_b)
        if result:
            return result
    # A larger set of pre-release fields has higher precedence if all
    # preceding identifiers are equal.
    return _cmp(len(a), len(b))


def compare_semver(a: str, b: str) -> int:
    """Compare two Semantic Versioning 2.0.0 strings.

    Returns -1 if a < b, 0 if a == b, and 1 if a > b according to the
    SemVer 2.0.0 precedence rules. Build metadata is ignored.
    """
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)
    if core_a != core_b:
        return -1 if core_a < core_b else 1
    return _compare_prerelease(pre_a, pre_b)
